// ---------------------------------------------------------------------------
// Darkroom (v6): a real photo darkroom. Sliders are exposure in EV (-2..2),
// contrast / saturation / temperature / highlights / shadows (-1..1),
// sharpen / clarity (0..1). Curves are per-channel tone curves: 5 control
// points each on [0,1]x[0,1], piecewise-linear. HSL shifts one hue family at
// a time: hue shift in degrees (-30..30), saturation scale (-1..1).
// ---------------------------------------------------------------------------
export const DARKROOM_CHANNELS = {
  luma: { label: 'Luma (all)' },
  red: { label: 'Red' },
  green: { label: 'Green' },
  blue: { label: 'Blue' },
};

export const HSL_CHANNELS = [
  { key: 'red', label: 'Red', hue: 0 },
  { key: 'orange', label: 'Orange', hue: 30 },
  { key: 'yellow', label: 'Yellow', hue: 60 },
  { key: 'green', label: 'Green', hue: 120 },
  { key: 'blue', label: 'Blue', hue: 240 },
  { key: 'magenta', label: 'Magenta', hue: 300 },
];

const IDENTITY_CURVE = [[0, 0], [0.25, 0.25], [0.5, 0.5], [0.75, 0.75], [1, 1]];

export function defaultDarkroom() {
  return {
    exposure: 0,
    contrast: 0,
    saturation: 0,
    temperature: 0,
    highlights: 0,
    shadows: 0,
    sharpen: 0,
    clarity: 0,
    curves: {
      luma: IDENTITY_CURVE.map((p) => [...p]),
      red: IDENTITY_CURVE.map((p) => [...p]),
      green: IDENTITY_CURVE.map((p) => [...p]),
      blue: IDENTITY_CURVE.map((p) => [...p]),
    },
    hsl: {
      red: { hue: 0, sat: 0 },
      orange: { hue: 0, sat: 0 },
      yellow: { hue: 0, sat: 0 },
      green: { hue: 0, sat: 0 },
      blue: { hue: 0, sat: 0 },
      magenta: { hue: 0, sat: 0 },
    },
  };
}

function cloneCurve(points) {
  return points.map((p) => [p[0], p[1]]);
}

function cloneDarkroom(dr) {
  const out = JSON.parse(JSON.stringify(dr || defaultDarkroom()));
  return out;
}

// One-click darkroom presets: a full curve set + slider set each. Golden
// Hour is warm with lifted shadows (sunset light); Blue Hour is cool with
// crushed shadows (night falling).
export const DARKROOM_PRESETS = {
  goldenHour: {
    label: 'Golden Hour',
    darkroom: {
      exposure: 0.3, contrast: 0.18, saturation: 0.28, temperature: 0.6,
      highlights: -0.12, shadows: 0.3, sharpen: 0.25, clarity: 0.2,
      curves: {
        luma: [[0, 0.02], [0.25, 0.28], [0.5, 0.53], [0.75, 0.78], [1, 0.98]],
        red: [[0, 0.03], [0.25, 0.29], [0.5, 0.55], [0.75, 0.80], [1, 1]],
        green: [[0, 0.01], [0.25, 0.26], [0.5, 0.51], [0.75, 0.76], [1, 0.98]],
        blue: [[0, 0], [0.25, 0.22], [0.5, 0.46], [0.75, 0.72], [1, 0.94]],
      },
      hsl: {
        red: { hue: 4, sat: 0.15 }, orange: { hue: 3, sat: 0.2 },
        yellow: { hue: 0, sat: 0.1 }, green: { hue: 0, sat: 0 },
        blue: { hue: 0, sat: 0 }, magenta: { hue: 0, sat: 0 },
      },
    },
  },
  blueHour: {
    label: 'Blue Hour',
    darkroom: {
      exposure: -0.15, contrast: 0.22, saturation: 0.15, temperature: -0.6,
      highlights: 0.1, shadows: -0.2, sharpen: 0.25, clarity: 0.25,
      curves: {
        luma: [[0, 0], [0.25, 0.22], [0.5, 0.47], [0.75, 0.74], [1, 0.97]],
        red: [[0, 0], [0.25, 0.21], [0.5, 0.45], [0.75, 0.71], [1, 0.93]],
        green: [[0, 0.01], [0.25, 0.24], [0.5, 0.49], [0.75, 0.75], [1, 0.97]],
        blue: [[0, 0.04], [0.25, 0.29], [0.5, 0.55], [0.75, 0.80], [1, 1]],
      },
      hsl: {
        red: { hue: 0, sat: 0 }, orange: { hue: 0, sat: 0 },
        yellow: { hue: 0, sat: 0 }, green: { hue: 0, sat: 0 },
        blue: { hue: -4, sat: 0.2 }, magenta: { hue: 0, sat: 0.1 },
      },
    },
  },
};

/** Applies a darkroom preset (curves + sliders + HSL) to the state.
 *  Returns false for unknown keys. */
export function applyDarkroomPreset(state, key) {
  const p = DARKROOM_PRESETS[key];
  if (!p) return false;
  state.darkroom = cloneDarkroom(p.darkroom);
  return true;
}

/** True when any darkroom control differs from its default. */
export function darkroomActive(dr) {
  if (!dr) return false;
  for (const k of ['exposure', 'contrast', 'saturation', 'temperature', 'highlights', 'shadows', 'sharpen', 'clarity']) {
    if (dr[k]) return true;
  }
  for (const ch of Object.keys(dr.curves || {})) {
    const pts = dr.curves[ch];
    const id = IDENTITY_CURVE;
    if (!pts || pts.length !== id.length) return true;
    for (let i = 0; i < id.length; i++) {
      if (Math.abs(pts[i][0] - id[i][0]) > 0.001 || Math.abs(pts[i][1] - id[i][1]) > 0.001) return true;
    }
  }
  for (const ch of Object.keys(dr.hsl || {})) {
    if (dr.hsl[ch].hue || dr.hsl[ch].sat) return true;
  }
  return false;
}

/** Builds a 256-entry lookup table from tone-curve control points
 *  (piecewise-linear through the points, sorted by x). */
export function buildCurveLUT(points) {
  const pts = [...points].sort((a, b) => a[0] - b[0]);
  const lut = new Uint8Array(256);
  for (let v = 0; v < 256; v++) {
    const t = v / 255;
    let y;
    if (t <= pts[0][0]) y = pts[0][1];
    else if (t >= pts[pts.length - 1][0]) y = pts[pts.length - 1][1];
    else {
      let i = 0;
      while (i < pts.length - 2 && t > pts[i + 1][0]) i++;
      const [x0, y0] = pts[i];
      const [x1, y1] = pts[i + 1];
      y = x1 === x0 ? y0 : y0 + ((y1 - y0) * (t - x0)) / (x1 - x0);
    }
    lut[v] = Math.max(0, Math.min(255, Math.round(y * 255)));
  }
  return lut;
}

// ---------------------------------------------------------------------------
// Smart Suggest (v6): reads the photo's real pixels — average brightness,
// contrast (luminance spread), saturation, warmth (red minus blue) and the
// dominant hue — then scores every grade against those measurements and
// returns the 3 best-fitting cover recipes. Nothing here is random: the same
// photo always suggests the same three covers, and each card cites the
// measurements that picked it.
// ---------------------------------------------------------------------------
export function analyzePixels(data, count) {
  let sumL = 0;
  let sumSq = 0;
  let sumR = 0;
  let sumG = 0;
  let sumB = 0;
  let sumSat = 0;
  const hueBins = new Array(12).fill(0);
  const HUE_NAMES = ['red', 'orange', 'gold', 'yellow', 'lime', 'green', 'teal', 'cyan', 'blue', 'violet', 'magenta', 'pink'];
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    const l = 0.299 * r + 0.587 * g + 0.114 * b;
    sumL += l;
    sumSq += l * l;
    sumR += r;
    sumG += g;
    sumB += b;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const sat = max === 0 ? 0 : (max - min) / max;
    sumSat += sat;
    if (max !== min && sat > 0.25) {
      const hue = rgbHue(r, g, b);
      if (hue >= 0) hueBins[Math.floor(hue / 30) % 12]++;
    }
  }
  const n = count || data.length / 4;
  const mean = sumL / n;
  const variance = Math.max(0, sumSq / n - mean * mean);
  const contrast = Math.min(1, Math.sqrt(variance) / 85);
  let bestBin = 0;
  for (let i = 1; i < 12; i++) if (hueBins[i] > hueBins[bestBin]) bestBin = i;
  const hueTotal = hueBins.reduce((a, b2) => a + b2, 0);
  return {
    brightness: mean / 255,
    contrast,
    saturation: sumSat / n,
    // Warmth: +1 = strongly red over blue, -1 = strongly blue over red.
    warmth: Math.max(-1, Math.min(1, (sumR - sumB) / n / 60)),
    dominantHue: bestBin * 30 + 15,
    dominantHueName: HUE_NAMES[bestBin],
    dominantHueShare: hueTotal ? hueBins[bestBin] / hueTotal : 0,
    samples: n,
  };
}

/** Samples an image's pixels (downscaled to 64x48) and returns the same
 *  analysis object as analyzePixels. */
export function analyzePhoto(img) {
  const c = document.createElement('canvas');
  c.width = 64;
  c.height = 48;
  const g = c.getContext('2d');
  g.drawImage(img, 0, 0, 64, 48);
  const data = g.getImageData(0, 0, 64, 48).data;
  return analyzePixels(data, 64 * 48);
}

const SUGGEST_RECIPES = [
  { grade: 'sunset', layout: 'hero', title: 'GOLDEN HOUR', titleStyle: 'extruded' },
  { grade: 'neon', layout: 'overlap', title: 'NEON NIGHTS', titleStyle: 'glow' },
  { grade: 'noir', layout: 'triptych', title: 'PALM NOIR', titleStyle: 'sticker' },
  { grade: 'sunsetNoir', layout: 'magazine', title: 'AFTER DARK', titleStyle: 'chrome' },
  { grade: 'pastel', layout: 'polaroid', title: 'PASTEL VICE', titleStyle: 'gradient' },
  { grade: 'heatwave', layout: 'magazine', title: 'HEATWAVE', titleStyle: 'curved' },
  { grade: 'chrome', layout: 'collage5', title: 'VICE CHROME', titleStyle: 'chrome' },
  { grade: 'comicpop', layout: 'storyboard', title: 'VICE POP', titleStyle: 'sticker' },
  { grade: 'sunbleach', layout: 'grid3', title: 'SUNBLEACH', titleStyle: 'flat' },
  { grade: 'inknoir', layout: 'collage5', title: 'VICE INK', titleStyle: 'flat' },
];

function scoreRecipe(recipe, a) {
  const warm = Math.max(0, a.warmth);
  const cool = Math.max(0, -a.warmth);
  const dark = 1 - a.brightness;
  const bright = a.brightness;
  const hue = a.dominantHue;
  const pinkish = (hue >= 300 || hue < 30) ? 1 : 0;
  const goldish = (hue >= 30 && hue < 75) ? 1 : 0;
  const blueish = (hue >= 180 && hue < 270) ? 1 : 0;
  switch (recipe.grade) {
    case 'sunset': return warm * 2 + bright * 0.8 + a.saturation * 0.8 + goldish * 1.2;
    case 'neon': return a.contrast * 1.2 + a.saturation * 1.2 + (pinkish || blueish) * 1.2 + cool * 0.5;
    case 'noir': return dark * 2 + a.contrast * 0.8 + (1 - a.saturation) * 0.6;
    case 'sunsetNoir': return dark * 1.4 + warm * 1 + a.contrast * 0.6;
    case 'pastel': return bright * 1.4 + (1 - a.contrast) * 1.2 + a.saturation * 0.5;
    case 'heatwave': return warm * 1.4 + bright * 0.8 + (1 - a.saturation) * 0.8;
    case 'chrome': return cool * 1.4 + a.contrast * 1 + blueish * 0.8;
    case 'comicpop': return a.saturation * 1.6 + a.contrast * 1 + bright * 0.4;
    case 'sunbleach': return bright * 1.2 + (1 - a.saturation) * 1 + (1 - a.contrast) * 0.6;
    case 'inknoir': return a.contrast * 1.2 + dark * 0.8 + (1 - a.saturation) * 1;
    default: return 0;
  }
}

/** Returns the 3 best cover recipes for a photo analysis, each with the
 *  measurements that picked it, as a human-readable reason. */
export function suggestCovers(a) {
  const scored = SUGGEST_RECIPES.map((r) => ({ ...r, score: scoreRecipe(r, a) }));
  scored.sort((x, y) => y.score - x.score);
  const top = scored.slice(0, 3);
  const evidence = `Brightness ${a.brightness.toFixed(2)} · contrast ${a.contrast.toFixed(2)} · `
    + `${a.warmth >= 0 ? 'warm' : 'cool'} ${Math.abs(a.warmth).toFixed(2)} · `
    + `${a.dominantHueName} dominates (${Math.round(a.dominantHueShare * 100)}% of coloured pixels)`;
  const reasons = {
    sunset: 'Warm, bright and saturated — Sunset grade deepens the golden light.',
    neon: 'High contrast and vivid colour — Neon grade turns it up after dark.',
    noir: 'Dark and moody — Palm Noir leans into the shadows.',
    sunsetNoir: 'Dark with warm embers — Sunset Noir keeps the glow, drops the light.',
    pastel: 'Bright and soft — Pastel Vice keeps it light and airy.',
    heatwave: 'Warm and washed — Heatwave duotone bakes the sun in.',
    chrome: 'Cool and contrasty — Neon Chrome polishes the blues.',
    comicpop: 'Saturated and punchy — Comic Pop makes it jump off the page.',
    sunbleach: 'Bright and faded — Sunbleach is the bleached-out summer print.',
    inknoir: 'Contrasty and drained — Ink Noir draws it in black and white.',
  };
  return top.map((r) => ({
    grade: r.grade,
    layout: r.layout,
    title: r.title,
    titleStyle: r.titleStyle,
    gradeLabel: GRADES[r.grade].label,
    layoutLabel: LAYOUTS[r.layout].label,
    score: Number(r.score.toFixed(2)),
    reason: `${reasons[r.grade]} ${evidence}`,
  }));
}

// ---------------------------------------------------------------------------
// Glitch / CRT effects (v7): chromatic aberration, scanlines, tracking
// noise, glitch slices and an RGB shift on the title. The pixel effects run
// as one post-pass over the finished cover (drawCover), the title fringe is
// drawn with the title itself — so both export into the PNG exactly as
// previewed. Slice/noise placement uses a fixed-seed PRNG, so the same
// state always renders the same glitch: a cover is reproducible, not a
// dice roll. Amounts: chromatic / title shift in px at 1080 wide (scaled
// with the canvas), scanlines / noise / slices as 0..1 strength.
// ---------------------------------------------------------------------------
export function defaultGlitch() {
  return {
    chromatic: { on: false, amount: 8 },
    scanlines: { on: false, amount: 0.5 },
    noise: { on: false, amount: 0.5 },
    slices: { on: false, amount: 0.5 },
    titleShift: { on: false, amount: 6 },
  };
}

/** True when any glitch effect is switched on. */
export function glitchActive(g) {
  if (!g) return false;
  return Object.values(g).some((fx) => fx && fx.on);
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Post-pass over the finished cover: RGB channel split, displaced slices,
 *  scanline darkening and VHS tracking-noise streaks. One pass over a
 *  source copy, so every effect composes instead of fighting. */
export function applyGlitch(ctx, W, H, glitch) {
  const img = ctx.getImageData(0, 0, W, H);
  const src = new Uint8ClampedArray(img.data);
  const d = img.data;
  const rnd = mulberry32(20261119);
  const scale = W / 1080;
  // Per-row horizontal displacement from the slice effect (0 = untouched).
  const rowShift = new Int16Array(H);
  if (glitch.slices && glitch.slices.on) {
    const amt = glitch.slices.amount || 0;
    const count = Math.round(2 + amt * 10);
    for (let i = 0; i < count; i++) {
      const y0 = Math.floor(rnd() * H);
      const hgt = Math.max(2, Math.round((4 + rnd() * 36) * scale));
      const dx = Math.round((rnd() < 0.5 ? -1 : 1) * (10 + rnd() * 60) * amt * scale);
      for (let y = y0; y < Math.min(H, y0 + hgt); y++) rowShift[y] = dx;
    }
  }
  // Per-row tracking-noise brightness lift (0 = untouched).
  const rowNoise = new Float32Array(H);
  if (glitch.noise && glitch.noise.on) {
    const amt = glitch.noise.amount || 0;
    const count = Math.round(amt * 24);
    for (let i = 0; i < count; i++) {
      const y0 = Math.floor(rnd() * H);
      const hgt = 1 + Math.floor(rnd() * 3);
      const lift = (40 + rnd() * 90) * amt;
      for (let y = y0; y < Math.min(H, y0 + hgt); y++) rowNoise[y] = Math.max(rowNoise[y], lift);
    }
  }
  const ca = (glitch.chromatic && glitch.chromatic.on)
    ? Math.max(1, Math.round((glitch.chromatic.amount || 0) * scale)) : 0;
  const scanAmt = (glitch.scanlines && glitch.scanlines.on) ? (glitch.scanlines.amount || 0) : 0;
  for (let y = 0; y < H; y++) {
    const shift = rowShift[y];
    const noise = rowNoise[y];
    const scan = scanAmt && y % 3 === 0 ? 1 - 0.35 * scanAmt : 1;
    const rowBase = y * W * 4;
    for (let x = 0; x < W; x++) {
      const o = rowBase + x * 4;
      const sx = Math.max(0, Math.min(W - 1, x + shift));
      const rx = Math.max(0, Math.min(W - 1, x - ca));
      const bx = Math.max(0, Math.min(W - 1, x + ca));
      let r = src[rowBase + rx * 4];
      let g = src[rowBase + sx * 4 + 1];
      let b = src[rowBase + bx * 4 + 2];
      if (scan !== 1) { r *= scan; g *= scan; b *= scan; }
      if (noise) { r += noise; g += noise; b += noise; }
      d[o] = r;
      d[o + 1] = g;
      d[o + 2] = b;
    }
  }
  ctx.putImageData(img, 0, 0);
}

// ---------------------------------------------------------------------------
// Procedural stickers (v7): small peel-and-stick art drawn in code — star,
// lightning bolt, mini palm, sun, neon heart — each with a die-cut white
// backing so it reads on any photo. Stickers sit on top of everything
// (after the bubbles), are draggable on the preview, and export into the
// PNG. Positions are centre fractions of the cover (x, y in 0..1).
// v16 adds five more (crown, shades, flame, dice, sparkle — 10 total) and
// a per-sticker colour: st.color overrides the kind's default fill, so
// the same shape can be pink, gold, cyan or any colour the user picks.
// v20 adds three more (palm tree, smiling sun, cassette — 13 total).
// Every sticker also carries its own size (st.size, 0.5x–2x, slider in
// the editor) — layoutStickers scales the hit box and the paint by it.
// ---------------------------------------------------------------------------
export const STICKER_KINDS = {
  star: { label: 'Star' },
  bolt: { label: 'Lightning bolt' },
  palm: { label: 'Mini palm' },
  sun: { label: 'Sun' },
  heart: { label: 'Neon heart' },
  crown: { label: 'Crown' },
  shades: { label: 'Sunglasses' },
  flame: { label: 'Flame' },
  dice: { label: 'Dice' },
  sparkle: { label: 'Sparkle star' },
  palmtree: { label: 'Palm tree' },
  sunface: { label: 'Smiling sun' },
  cassette: { label: 'Cassette' },
};

export const STICKER_DEFAULT_COLORS = {
  star: '#ffb400', bolt: '#ffe600', palm: '#160a24', sun: '#ff6b35',
  heart: '#ff2e88', crown: '#ffb400', shades: '#111111', flame: '#ff6b35',
  dice: '#ffffff', sparkle: '#00e5ff',
  palmtree: '#2d8a4e', sunface: '#ffb400', cassette: '#ff2e88',
};

export function stickerColor(st) {
  return (st && st.color) || STICKER_DEFAULT_COLORS[(st && st.kind) || 'star'] || '#ffb400';
}

export function defaultStickers() {
  return [{ kind: 'star', x: 0.85, y: 0.16, size: 1, rot: 12 }];
}

/** Hit-test boxes for the stickers, in canvas pixels (same numbers the
 *  draw uses, so the editor's drag matches exactly what is painted). */
export function layoutStickers(W, H, state) {
  const out = [];
  for (const st of state.stickers || []) {
    const r = Math.min(W, H) * 0.055 * (st.size || 1);
    const w = r * 2.6;
    out.push({
      ...st,
      cx: st.x * W,
      cy: st.y * H,
      r,
      x: st.x * W - w / 2,
      y: st.y * H - w / 2,
      w,
      h: w,
    });
  }
  return out;
}

function drawStickerShape(ctx, kind, r, color) {
  // Drawn centred on (0, 0), radius ~r. `color` is the sticker's own
  // colour (v16 picker) — it replaces the kind's default main fill.
  const fill = color || '#ffb400';
  if (kind === 'crown') {
    ctx.beginPath();
    const pts = [[-0.9, 0.55], [-0.9, -0.25], [-0.45, 0.15], [0, -0.65], [0.45, 0.15], [0.9, -0.25], [0.9, 0.55]];
    pts.forEach(([px, py], i) => { if (i === 0) ctx.moveTo(px * r, py * r); else ctx.lineTo(px * r, py * r); });
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.08);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
    // Jewels on the three peaks.
    ctx.fillStyle = '#ff2e88';
    for (const [jx, jy] of [[-0.9, -0.25], [0, -0.65], [0.9, -0.25]]) {
      ctx.beginPath(); ctx.arc(jx * r, jy * r, r * 0.14, 0, Math.PI * 2); ctx.fill();
    }
    ctx.fillStyle = '#00e5ff';
    ctx.fillRect(-r * 0.9, r * 0.28, r * 1.8, r * 0.22);
  } else if (kind === 'shades') {
    // Two dark lenses + bridge + temples, GTA-poster sunglasses.
    ctx.fillStyle = fill;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = Math.max(2, r * 0.09);
    for (const cx of [-0.52, 0.52]) {
      ctx.beginPath();
      ctx.ellipse(cx * r, 0, r * 0.46, r * 0.38, 0, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(-r * 0.08, -r * 0.05); ctx.lineTo(r * 0.08, -r * 0.05);
    ctx.lineWidth = Math.max(2, r * 0.12); ctx.strokeStyle = fill; ctx.stroke();
    // Glint on each lens.
    ctx.strokeStyle = 'rgba(255,255,255,0.85)';
    ctx.lineWidth = Math.max(2, r * 0.08);
    for (const cx of [-0.52, 0.52]) {
      ctx.beginPath(); ctx.moveTo((cx - 0.2) * r, r * 0.18); ctx.lineTo((cx + 0.12) * r, -r * 0.16); ctx.stroke();
    }
  } else if (kind === 'flame') {
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.bezierCurveTo(r * 0.55, -r * 0.35, r * 0.85, r * 0.1, r * 0.6, r * 0.55);
    ctx.bezierCurveTo(r * 0.4, r * 0.95, -r * 0.4, r * 0.95, -r * 0.6, r * 0.55);
    ctx.bezierCurveTo(-r * 0.85, r * 0.1, -r * 0.55, -r * 0.35, 0, -r);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.08);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, -r * 0.25);
    ctx.bezierCurveTo(r * 0.3, r * 0.1, r * 0.35, r * 0.35, r * 0.15, r * 0.55);
    ctx.bezierCurveTo(0, r * 0.68, -r * 0.3, r * 0.6, -r * 0.28, r * 0.3);
    ctx.bezierCurveTo(-r * 0.25, r * 0.05, -r * 0.15, -r * 0.05, 0, -r * 0.25);
    ctx.closePath();
    ctx.fillStyle = '#ffe600';
    ctx.fill();
  } else if (kind === 'dice') {
    const lw = Math.max(2, r * 0.08);
    roundRectPath(ctx, -r * 0.85, -r * 0.85, r * 1.7, r * 1.7, r * 0.28);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = lw;
    ctx.strokeStyle = '#1a1a1a';
    ctx.stroke();
    // Five pips; white on a dark die, dark on a light one.
    const dark = /^#([0-9a-f]{6})$/i.test(fill)
      && (parseInt(fill.slice(1, 3), 16) * 0.299 + parseInt(fill.slice(3, 5), 16) * 0.587 + parseInt(fill.slice(5, 7), 16) * 0.114) < 110;
    ctx.fillStyle = dark ? '#ffffff' : '#1a1a1a';
    for (const [px, py] of [[-0.45, -0.45], [0.45, -0.45], [0, 0], [-0.45, 0.45], [0.45, 0.45]]) {
      ctx.beginPath(); ctx.arc(px * r, py * r, r * 0.14, 0, Math.PI * 2); ctx.fill();
    }
  } else if (kind === 'sparkle') {
    // Four-point sparkle star, drawn with curved arms.
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.quadraticCurveTo(r * 0.16, -r * 0.16, r, 0);
    ctx.quadraticCurveTo(r * 0.16, r * 0.16, 0, r);
    ctx.quadraticCurveTo(-r * 0.16, r * 0.16, -r, 0);
    ctx.quadraticCurveTo(-r * 0.16, -r * 0.16, 0, -r);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.08);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
  } else if (kind === 'bolt') {
    ctx.beginPath();
    const pts = [[0.15, -1], [-0.45, 0.15], [-0.05, 0.15], [-0.25, 1], [0.5, -0.15], [0.05, -0.15]];
    pts.forEach(([px, py], i) => {
      if (i === 0) ctx.moveTo(px * r, py * r);
      else ctx.lineTo(px * r, py * r);
    });
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.08);
    ctx.strokeStyle = '#ff2e88';
    ctx.stroke();
  } else if (kind === 'palm') {
    drawOnePalm(ctx, -r * 0.2, r * 0.9, r * 1.5, fill);
  } else if (kind === 'sun') {
    ctx.strokeStyle = '#ff9d00';
    ctx.lineWidth = Math.max(2, r * 0.12);
    ctx.lineCap = 'round';
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * r * 0.55, Math.sin(a) * r * 0.55);
      ctx.lineTo(Math.cos(a) * r * 0.98, Math.sin(a) * r * 0.98);
      ctx.stroke();
    }
    const g = ctx.createRadialGradient(0, 0, r * 0.1, 0, 0, r * 0.55);
    g.addColorStop(0, '#fff7d6');
    g.addColorStop(1, '#ff6b35');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.55, 0, Math.PI * 2);
    ctx.fill();
  } else if (kind === 'palmtree') {
    // v20: a full palm tree — TWO palms (one tall, one short, leaning
    // apart) with coconuts, in the sticker's own green. Distinct from
    // the v7 'palm' (a single mini palm silhouette): this one is a
    // pair, so it reads as a tree, not a frond.
    drawOnePalm(ctx, -r * 0.55, r * 0.95, r * 1.5, fill);
    drawOnePalm(ctx, r * 0.15, r * 0.95, r * 1.05, fill);
  } else if (kind === 'sunface') {
    // v20: a smiling sun — triangular rays, a warm disc, two dot eyes
    // and a smile arc. Distinct from the v7 'sun' (rays + plain
    // gradient disc, no face): the face makes it a character.
    ctx.fillStyle = fill;
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a - 0.06) * r * 0.62, Math.sin(a - 0.06) * r * 0.62);
      ctx.lineTo(Math.cos(a) * r * 1.02, Math.sin(a) * r * 1.02);
      ctx.lineTo(Math.cos(a + 0.06) * r * 0.62, Math.sin(a + 0.06) * r * 0.62);
      ctx.closePath();
      ctx.fill();
    }
    const g = ctx.createRadialGradient(0, 0, r * 0.1, 0, 0, r * 0.62);
    g.addColorStop(0, '#fff7d6');
    g.addColorStop(1, fill);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.62, 0, Math.PI * 2);
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.07);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
    // Face: two dot eyes + a smile arc, in dark brown.
    ctx.fillStyle = '#7a4a21';
    ctx.beginPath(); ctx.arc(-r * 0.2, -r * 0.08, r * 0.07, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(r * 0.2, -r * 0.08, r * 0.07, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#7a4a21';
    ctx.lineWidth = Math.max(2, r * 0.07);
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.arc(0, r * 0.05, r * 0.28, Math.PI * 0.15, Math.PI * 0.85); ctx.stroke();
  } else if (kind === 'cassette') {
    // v20: a cassette tape — a rounded body in the sticker's colour, a
    // white label strip across the top, two reels with spokes and a
    // tape window between them. The 80s, peel-and-stick.
    const lw = Math.max(2, r * 0.07);
    roundRectPath(ctx, -r * 0.95, -r * 0.6, r * 1.9, r * 1.2, r * 0.18);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = lw;
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
    ctx.fillStyle = 'rgba(255, 255, 255, 0.92)';
    ctx.fillRect(-r * 0.95, -r * 0.6, r * 1.9, r * 0.42);
    for (const cx of [-0.45, 0.45]) {
      ctx.beginPath();
      ctx.arc(cx * r, r * 0.18, r * 0.26, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.fill();
      ctx.lineWidth = lw * 0.8;
      ctx.strokeStyle = '#1a1a1a';
      ctx.stroke();
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = Math.max(2, r * 0.05);
      for (let i = 0; i < 3; i++) {
        const a = (i / 3) * Math.PI * 2 + 0.5;
        ctx.beginPath();
        ctx.moveTo(cx * r, r * 0.18);
        ctx.lineTo(cx * r + Math.cos(a) * r * 0.22, r * 0.18 + Math.sin(a) * r * 0.22);
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.arc(cx * r, r * 0.18, r * 0.06, 0, Math.PI * 2);
      ctx.fillStyle = '#1a1a1a';
      ctx.fill();
    }
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = Math.max(2, r * 0.05);
    ctx.beginPath();
    ctx.moveTo(-r * 0.19, r * 0.18);
    ctx.lineTo(r * 0.19, r * 0.18);
    ctx.stroke();
  } else if (kind === 'heart') {
    ctx.beginPath();
    ctx.moveTo(0, r * 0.6);
    ctx.bezierCurveTo(-r, -r * 0.1, -r * 0.5, -r * 0.9, 0, -r * 0.3);
    ctx.bezierCurveTo(r * 0.5, -r * 0.9, r, -r * 0.1, 0, r * 0.6);
    ctx.closePath();
    ctx.shadowColor = fill;
    ctx.shadowBlur = r * 0.5;
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.lineWidth = Math.max(2, r * 0.1);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
  } else {
    // 'star' and any unknown kind: a 5-point star.
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + (i * Math.PI) / 5;
      const rad = i % 2 === 0 ? r : r * 0.45;
      const px = Math.cos(ang) * rad;
      const py = Math.sin(ang) * rad;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.1);
    ctx.strokeStyle = '#ffffff';
    ctx.stroke();
  }
}

function drawStickers(ctx, W, H, state) {
  const items = layoutStickers(W, H, state);
  for (const it of items) {
    ctx.save();
    ctx.translate(it.cx, it.cy);
    ctx.rotate(((it.rot || 0) * Math.PI) / 180);
    // Die-cut white backing, like a real sticker.
    ctx.beginPath();
    ctx.arc(0, 0, it.r * 1.28, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = 'rgba(0,0,0,0.45)';
    ctx.shadowBlur = it.r * 0.25;
    ctx.shadowOffsetY = it.r * 0.08;
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.shadowOffsetY = 0;
    drawStickerShape(ctx, it.kind, it.r, stickerColor(it));
    ctx.restore();
  }
}

// ---------------------------------------------------------------------------
// Auto-caption (v7): the same pixel reading as Smart Suggest, turned into
// titles. Deterministic: the same photo always suggests the same three
// captions, each citing the measurements that picked it. The first is the
// best fit for the photo's light + temperature; the next two come from the
// dominant hue, the saturation, or the brightness — so the three are
// always different covers, not three wordings of one idea.
// ---------------------------------------------------------------------------
export function suggestCaptions(a) {
  const warm = a.warmth >= 0.15;
  const cool = a.warmth <= -0.15;
  const dark = a.brightness < 0.42;
  const bright = a.brightness > 0.62;
  const vivid = a.saturation > 0.45;
  const hue = a.dominantHueName || '';
  const ev = `Brightness ${a.brightness.toFixed(2)} · ${a.warmth >= 0 ? 'warm' : 'cool'} ${Math.abs(a.warmth).toFixed(2)} · ${hue} dominates`;
  const cands = [];
  if (warm && dark) cands.push({ title: 'VICE CITY NIGHTS', tagline: 'The city never sleeps — it just changes colour.', why: 'Warm and dark: a night cover in golden light.' });
  if (warm && bright) cands.push({ title: 'GOLDEN HOUR', tagline: 'Chase the sun till the palms run out.', why: 'Warm and bright: the golden hour, bottled.' });
  if (cool && dark) cands.push({ title: 'NEON AFTER DARK', tagline: 'Lights on. Brakes off. Vice City after midnight.', why: 'Cool and dark: neon does the talking.' });
  if (cool && bright) cands.push({ title: 'BLUE HOUR', tagline: 'Ten minutes when the whole city turns blue.', why: 'Cool and bright: the blue hour before night.' });
  if (!warm && !cool) cands.push({ title: 'VICE LIGHTS', tagline: 'One city. One night. No brakes.', why: 'Balanced light: the classic Vice cover.' });
  if (hue === 'pink' || hue === 'magenta' || hue === 'red') cands.push({ title: 'PINK PALMS', tagline: 'Bubblegum sunset, palm-tree shade.', why: `${hue} dominates the frame.` });
  if (hue === 'gold' || hue === 'yellow' || hue === 'orange') cands.push({ title: 'GOLD RUSH', tagline: 'Every street paved in late light.', why: `${hue} dominates the frame.` });
  if (hue === 'blue' || hue === 'cyan' || hue === 'teal') cands.push({ title: 'MIDNIGHT BLUE', tagline: 'Deep water, deeper neon.', why: `${hue} dominates the frame.` });
  if (hue === 'green' || hue === 'lime') cands.push({ title: 'PALM GREEN', tagline: 'Where the palms bend, the city follows.', why: `${hue} dominates the frame.` });
  if (hue === 'violet') cands.push({ title: 'VIOLET HOUR', tagline: 'Purple sky, pink pavement.', why: `${hue} dominates the frame.` });
  if (vivid) cands.push({ title: 'VICE POP', tagline: 'Turn it up till the neon buzzes.', why: 'Saturation is high — the colours want to shout.' });
  if (dark) cands.push({ title: 'AFTER DARK', tagline: 'What happens after dark stays on the cover.', why: 'A dark frame: lean into the night.' });
  if (bright) cands.push({ title: 'SUNBLEACH', tagline: 'Bleached by the sun, kept by the city.', why: 'A bright frame: the bleached-out summer print.' });
  cands.push({ title: 'VICE LIGHTS', tagline: 'One city. One night. No brakes.', why: 'The house classic — always a safe cover.' });
  // Guaranteed fallbacks, so the three cards always fill even for a photo
  // that is neither warm nor cool, neither dark nor bright, and not vivid.
  cands.push({ title: 'PALM NOIR', tagline: 'Shadows, palms and a city that never blinks.', why: 'A moody all-rounder for any light.' });
  cands.push({ title: 'NEON NIGHTS', tagline: 'The strip never sleeps and neither do you.', why: 'Neon fits every Vice cover.' });
  cands.push({ title: 'HEATWAVE', tagline: 'Baked sun, buzzing streets, no shade.', why: 'Heat fits every Vice cover.' });
  const seen = new Set();
  const out = [];
  for (const c of cands) {
    if (seen.has(c.title)) continue;
    seen.add(c.title);
    out.push({ ...c, reason: `${c.why} ${ev}` });
    if (out.length === 3) break;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Auto-caption v2 (v18): three NEW deterministic styles on the same pixel
// reading, so the panel now offers six caption cards in all (v7's three +
// these three). Each style returns exactly one card — the best fit for the
// photo — and each card carries title + tagline + cover lines that belong
// together, so one click applies a consistent cover voice:
//   Tagline Punch — a short, loud slogan (the cover's shout).
//   Movie Credit Line — a film-poster billing block under the title: the
//     tagline plus two credit lines ("A ... PICTURE" / "STARRING ...").
//   Neon Slogan — a neon slogan built around a keyword from the title.
// Deterministic like v7: the same photo always suggests the same three.
// ---------------------------------------------------------------------------
export function suggestCaptionsV2(a) {
  const warm = a.warmth >= 0.15;
  const cool = a.warmth <= -0.15;
  const dark = a.brightness < 0.42;
  const bright = a.brightness > 0.62;
  const vivid = a.saturation > 0.45;
  const hue = a.dominantHueName || '';
  const ev = `Brightness ${a.brightness.toFixed(2)} · ${a.warmth >= 0 ? 'warm' : 'cool'} ${Math.abs(a.warmth).toFixed(2)} · ${hue} dominates`;
  // --- Style 1: Tagline Punch — short, loud, one breath. ---
  const punch = [];
  if (warm && dark) punch.push({ title: 'NIGHT SHIFT', tagline: 'Own the night.', coverLines: ['The city after midnight', 'No brakes. No curfew.'] });
  if (warm && bright) punch.push({ title: 'SUN CHASER', tagline: 'Faster than the sunset.', coverLines: ['180 mph into golden hour', 'The coast never looked back'] });
  if (cool && dark) punch.push({ title: 'AFTER MIDNIGHT', tagline: 'Neon on. Fear off.', coverLines: ['The strip lights itself', 'Every shadow has a story'] });
  if (cool && bright) punch.push({ title: 'BLUE STREAK', tagline: 'Ten minutes of blue. Forever.', coverLines: ['The hour the city turns blue', 'Catch it or miss it'] });
  if (hue === 'pink' || hue === 'magenta' || hue === 'red') punch.push({ title: 'PINK THUNDER', tagline: 'Loud pink. Louder nights.', coverLines: ['Bubblegum sky, lead foot', 'Vice City in full colour'] });
  if (hue === 'gold' || hue === 'yellow' || hue === 'orange') punch.push({ title: 'GOLD STANDARD', tagline: 'Every street paved in gold.', coverLines: ['Late light, full throttle', 'The golden hour, kept'] });
  if (hue === 'blue' || hue === 'cyan' || hue === 'teal') punch.push({ title: 'DEEP END', tagline: 'Dive in. The neon is warm.', coverLines: ['Deep water, deeper lights', 'The coast after dark'] });
  if (vivid) punch.push({ title: 'FULL BLAST', tagline: 'Turn it up till it buzzes.', coverLines: ['Colour at maximum volume', 'No such thing as too much'] });
  if (dark) punch.push({ title: 'DARK HORSE', tagline: 'The night backs the bold.', coverLines: ['Shadows do the talking', 'The city never blinks'] });
  if (bright) punch.push({ title: 'HIGH NOON', tagline: 'Bleached sun. Zero shade.', coverLines: ['Summer, turned all the way up', 'Sunglasses required'] });
  punch.push({ title: 'VICE LOUD', tagline: 'If it is not loud, it is not Vice.', coverLines: ['One city. One night.', 'Turn the volume up'] });
  // --- Style 2: Movie Credit Line — film-poster billing under the title. ---
  const hueWord = hue ? hue.toUpperCase() : 'VICE';
  const credit = [];
  if (dark) credit.push({ title: 'CITY OF SHADOWS', tagline: 'A story told after dark.', coverLines: [`A ${hueWord} PICTURE`, 'STARRING THE NIGHT ITSELF'] });
  if (bright) credit.push({ title: 'SUMMER BLOCKBUSTER', tagline: 'The season\'s loudest picture.', coverLines: ['A VICE CITY PICTURE', 'STARRING THE SUN AND THE STRIP'] });
  if (warm) credit.push({ title: 'GOLDEN REEL', tagline: 'Shot in the last light of day.', coverLines: ['A GOLDEN HOUR PICTURE', 'STARRING EVERY PALM IN TOWN'] });
  if (cool) credit.push({ title: 'NEON REEL', tagline: 'Filmed where the lights never go out.', coverLines: ['A NEON PICTURE', 'STARRING THE WHOLE BOULEVARD'] });
  if (vivid) credit.push({ title: 'TECHNICOLOR VICE', tagline: 'In glorious, unapologetic colour.', coverLines: ['A VICE CITY PICTURE', 'STARRING EVERY COLOUR AT ONCE'] });
  credit.push({ title: 'VICE CITY', tagline: 'The picture event of the summer.', coverLines: ['A VICE CITY PICTURE', 'STARRING THE CITY ITSELF'] });
  // --- Style 3: Neon Slogan — a neon slogan keyed off the title word. ---
  const neon = [];
  if (warm && dark) neon.push({ title: 'VICE CITY NIGHTS', tagline: 'NEON NEVER SLEEPS IN VICE CITY.', coverLines: ['Neon nights, every night', 'The sign is always on'] });
  if (warm && bright) neon.push({ title: 'GOLDEN HOUR', tagline: 'THE SUN SETS. THE NEON RISES.', coverLines: ['Golden by day, neon by night', 'Two sunsets, one city'] });
  if (cool && dark) neon.push({ title: 'NEON AFTER DARK', tagline: 'FOLLOW THE NEON HOME.', coverLines: ['The glow knows the way', 'Midnight, lit in pink'] });
  if (hue === 'pink' || hue === 'magenta' || hue === 'red') neon.push({ title: 'PINK PALMS', tagline: 'PINK IS THE NEW BLACK.', coverLines: ['Bubblegum neon, palm shade', 'Pink pavement, pink sky'] });
  if (hue === 'gold' || hue === 'yellow' || hue === 'orange') neon.push({ title: 'GOLD RUSH', tagline: 'STRUCK GOLD ON EVERY STREET.', coverLines: ['Gold light, gold nights', 'The rush never ends'] });
  if (hue === 'blue' || hue === 'cyan' || hue === 'teal') neon.push({ title: 'MIDNIGHT BLUE', tagline: 'BLUE LIGHTS. BIG CITY. NO SLEEP.', coverLines: ['Deep blue, deep neon', 'The water glows back'] });
  if (vivid) neon.push({ title: 'VICE POP', tagline: 'NEON LOUD, PROUD, AND ALWAYS ON.', coverLines: ['Pop colour, pop nights', 'The buzz never fades'] });
  neon.push({ title: 'NEON NIGHTS', tagline: 'THE STRIP NEVER SLEEPS.', coverLines: ['Neon on every corner', 'The night is electric'] });
  const pick = (list, style, why) => {
    const c = list[0];
    return { style, title: c.title, tagline: c.tagline, coverLines: [...c.coverLines], reason: `${why} ${ev}` };
  };
  return [
    pick(punch, 'Tagline Punch', 'Short and loud: the cover\'s shout.'),
    pick(credit, 'Movie Credit Line', 'Film-poster billing under the title.'),
    pick(neon, 'Neon Slogan', 'A neon slogan keyed off the title.'),
  ];
}

// ---------------------------------------------------------------------------
// Auto-caption v3 (v21): three NEW deterministic styles on the same pixel
// reading, so the panel now offers nine caption cards in all (v7's three +
// v2's three + these three). Each style returns exactly one card — the best
// fit for the photo — and each card carries title + tagline + cover lines
// that belong together, so one click applies a consistent cover voice:
//   Retro Ad — 1980s ad copy: the hard sell, the exclamation, the "as
//     seen on TV" footnotes. ("NOW WITH 100% MORE NEON!")
//   Breaking News — the emergency headline: BREAKING, LIVE FROM, the
//     developing-story crawl under the title.
//   Album Liner — liner-notes voice: the record sleeve, side A / side B,
//     "recorded live in Vice City", the track listing as cover lines.
// Deterministic like v7/v2: the same photo always suggests the same three.
// ---------------------------------------------------------------------------
export function suggestCaptionsV3(a) {
  const warm = a.warmth >= 0.15;
  const cool = a.warmth <= -0.15;
  const dark = a.brightness < 0.42;
  const bright = a.brightness > 0.62;
  const vivid = a.saturation > 0.45;
  const hue = a.dominantHueName || '';
  const ev = `Brightness ${a.brightness.toFixed(2)} · ${a.warmth >= 0 ? 'warm' : 'cool'} ${Math.abs(a.warmth).toFixed(2)} · ${hue} dominates`;
  // --- Style 1: Retro Ad — the 80s hard sell. ---
  const retro = [];
  if (warm && dark) retro.push({ title: 'VICE CITY NIGHTS', tagline: 'Now with 100% more neon — as seen on TV!', coverLines: ['As seen on TV', 'At fine video stores everywhere'] });
  if (warm && bright) retro.push({ title: 'GOLDEN HOUR', tagline: 'The sun never looked this good — order now!', coverLines: ['Operators are standing by', 'Satisfaction guaranteed or your sunset back'] });
  if (cool && dark) retro.push({ title: 'NEON AFTER DARK', tagline: 'Lights on. Brakes off. Batteries included!', coverLines: ['As seen on TV', 'Not available in stores — call now'] });
  if (hue === 'pink' || hue === 'magenta' || hue === 'red') retro.push({ title: 'PINK PALMS', tagline: 'Bubblegum pink — now in glorious Technicolor!', coverLines: ['As seen on TV', 'Pink is the new black'] });
  if (hue === 'gold' || hue === 'yellow' || hue === 'orange') retro.push({ title: 'GOLD RUSH', tagline: 'Every street paved in gold — act now, supplies limited!', coverLines: ['As seen on TV', 'Gold light, gold nights, gold price'] });
  if (hue === 'blue' || hue === 'cyan' || hue === 'teal') retro.push({ title: 'MIDNIGHT BLUE', tagline: 'Deep blue, deeper neon — the colour TV was invented for!', coverLines: ['As seen on TV', 'In glorious living colour'] });
  if (vivid) retro.push({ title: 'VICE POP', tagline: 'New! Improved! Louder! Now with extra colour!', coverLines: ['As seen on TV', 'Colour at maximum volume'] });
  if (dark) retro.push({ title: 'AFTER DARK', tagline: 'What happens after dark — now on home video!', coverLines: ['As seen on TV', 'Parental guidance suggested'] });
  if (bright) retro.push({ title: 'SUNBLEACH', tagline: 'Bleached by the sun — the summer you will never forget!', coverLines: ['As seen on TV', 'Sunglasses sold separately'] });
  retro.push({ title: 'VICE LIGHTS', tagline: 'One city. One night. No brakes. Order today!', coverLines: ['As seen on TV', 'The house classic — now on sale'] });
  // --- Style 2: Breaking News — the emergency headline. ---
  const news = [];
  if (dark) news.push({ title: 'BREAKING: VICE CITY', tagline: 'Live from the strip — the city that never sleeps.', coverLines: ['Live from the strip', 'Developing story'] });
  if (bright) news.push({ title: 'BREAKING: GOLDEN HOUR', tagline: 'Live from the coast — the sun refuses to set.', coverLines: ['Live from the boulevard', 'Developing story'] });
  if (warm) news.push({ title: 'BREAKING: HEATWAVE', tagline: 'Live from downtown — temperatures hit record neon.', coverLines: ['Live from the strip', 'More at eleven'] });
  if (cool) news.push({ title: 'BREAKING: BLUE HOUR', tagline: 'Live from the waterfront — the city turns blue.', coverLines: ['Live from the pier', 'Developing story'] });
  if (vivid) news.push({ title: 'BREAKING: COLOUR ALERT', tagline: 'Live from Vice City — saturation at maximum.', coverLines: ['Live from the strip', 'Stay tuned'] });
  news.push({ title: 'BREAKING: VICE CITY', tagline: 'Live from the strip — the night is just beginning.', coverLines: ['Live from the strip', 'Developing story'] });
  // --- Style 3: Album Liner — the record sleeve. ---
  const liner = [];
  if (warm && dark) liner.push({ title: 'VICE CITY NIGHTS', tagline: 'Side A, track 1: the city after midnight.', coverLines: ['Recorded live in Vice City', 'All songs written under neon light'] });
  if (warm && bright) liner.push({ title: 'GOLDEN HOUR', tagline: 'Side A, track 1: chase the sun till it sets.', coverLines: ['Recorded live on the boulevard', 'Produced by the last light of day'] });
  if (cool && dark) liner.push({ title: 'NEON AFTER DARK', tagline: 'Side B, track 1: follow the neon home.', coverLines: ['Recorded live after midnight', 'Mixed in the glow of the strip'] });
  if (hue === 'pink' || hue === 'magenta' || hue === 'red') liner.push({ title: 'PINK PALMS', tagline: 'Side A, track 1: bubblegum sunset, palm-tree shade.', coverLines: ['Recorded live in Vice City', 'Pressed on pink vinyl'] });
  if (hue === 'gold' || hue === 'yellow' || hue === 'orange') liner.push({ title: 'GOLD RUSH', tagline: 'Side A, track 1: every street paved in late light.', coverLines: ['Recorded live at golden hour', 'All songs written in the sun'] });
  if (hue === 'blue' || hue === 'cyan' || hue === 'teal') liner.push({ title: 'MIDNIGHT BLUE', tagline: 'Side B, track 1: deep water, deeper neon.', coverLines: ['Recorded live on the waterfront', 'Mixed under a blue moon'] });
  if (vivid) liner.push({ title: 'VICE POP', tagline: 'Side A, track 1: turn it up till the neon buzzes.', coverLines: ['Recorded live in full colour', 'Play loud — very loud'] });
  liner.push({ title: 'VICE LIGHTS', tagline: 'Side A, track 1: one city, one night, no brakes.', coverLines: ['Recorded live in Vice City', 'All songs written under neon light'] });
  const pick = (list, style, why) => {
    const c = list[0];
    return { style, title: c.title, tagline: c.tagline, coverLines: [...c.coverLines], reason: `${why} ${ev}` };
  };
  return [
    pick(retro, 'Retro Ad', '1980s ad copy: the hard sell, the exclamation, the TV footnote.'),
    pick(news, 'Breaking News', 'The emergency headline: BREAKING, LIVE FROM, the crawl.'),
    pick(liner, 'Album Liner', 'The record sleeve: side A / side B, recorded live.'),
  ];
}

