    ctx.lineTo(w * 0.02, h * 0.1);
    ctx.lineTo(-w * 0.08, h * 0.9);
    ctx.lineTo(w * 0.22, -h * 0.1);
    ctx.lineTo(-w * 0.02, -h * 0.1);
