/** Applies a template (same fields as a Look, plus the Photo Lab settings).
 *  Returns false for unknown keys. */
export function applyTemplate(state, key) {
  const t = TEMPLATES[key];
  if (!t) return false;
  for (const f of ['layout', 'grade', 'backdrop', 'blend', 'titleStyle', 'treatment', 'masthead', 'coverLinesOn', 'title']) {
    if (t[f] !== undefined) state[f] = t[f];
  }
  // v14 fix: templates that name their fonts (viceFonts / viceShowcase /
  // vicePrint / viceComplete) now actually apply them — before v14
  // applyTemplate never copied titleFont/bodyFont, so clicking one of
  // those templates silently kept the previous faces.
  if (t.titleFont) state.titleFont = t.titleFont;
  if (t.bodyFont) state.bodyFont = t.bodyFont;
  // v18: a template that names its tagline / cover lines / grain applies
  // them too (Vice Layouts ships a Neon Slogan tagline + credit lines +
  // heavy grain — before v18 applyTemplate never copied those, so the
  // template's voice was lost on click).
  if (t.tagline !== undefined) state.tagline = t.tagline;
  if (t.coverLines) state.coverLines = [...t.coverLines];
  if (t.grain !== undefined) state.grain = t.grain;
  // v15: a template that names its Title FX applies it whole.
  if (t.titleFx) state.titleFx = { ...t.titleFx };
  if (t.lab) {
    state.blur = t.lab.blur || 0;
    state.spotlight = t.lab.spotlight || 0;
    state.colorPop = t.lab.colorPop || 'none';
    state.film = t.lab.film || 'none';
  }
  if (t.darkroom) state.darkroom = JSON.parse(JSON.stringify(t.darkroom));
  if (t.tilt) state.tilt = { ...t.tilt };
  if (t.glitch) state.glitch = JSON.parse(JSON.stringify(t.glitch));
  if (t.palette) state.palette = JSON.parse(JSON.stringify(t.palette));
  if (t.frame) state.frame = t.frame;
  // v17: a template that names its Neon frame colour applies it, and one
  // that names a harmony applies the scheme (Title FX from the scheme,
  // recomputed — so the template's colours always match colorHarmonies).
  if (t.frameColor) state.frameColor = t.frameColor;
  if (t.harmony && t.harmony.scheme) {
    applyHarmony(state, t.harmony.scheme, t.harmony.base);
  }
  if (t.customSize) state.customSize = { ...t.customSize };
  // v23: a template that names its Magazine Furniture applies it whole
  // (Vice Key Art ships the barcode + ISSUE 07 • NOV 2026 • $9.99 on).
  if (t.furniture) state.furniture = { ...defaultFurniture(), ...t.furniture };
  // v24: a template that names its Vice Clock applies it whole (Vice
  // Golden Hour ships the clock on at 18:30).
  if (t.timeOfDay) state.timeOfDay = { ...defaultTimeOfDay(), ...t.timeOfDay };
  // v25: a template that names its Vice Weather applies it whole (Vice
  // Storm ships Storm on at 80%).
  if (t.weather) state.weather = { ...defaultWeather(), ...t.weather };
  // v26: a template that names its Vice Era applies it whole (Vice 1986
  // ships 1986 on at 80%).
  if (t.era) state.era = { ...defaultEra(), ...t.era };
  // v27: a template that names its Vice District applies it whole (Vice
  // Ocean Drive ships Ocean Drive on at 80%).
  if (t.district) state.district = { ...defaultDistrict(), ...t.district };
  // v28: a template that names its Vice Moment applies it whole AND
  // conducts the other dials (Vice Sunset Heist ships the heist moment
  // on at 80% — the recipe sets clock + weather + era + district +
  // grade + backdrop in one click). Runs last so the recipe wins over
  // any sub-dial the template also names.
  if (t.moment) {
    state.moment = { ...defaultMoment(), ...t.moment };
    if (state.moment.on) applyMoment(state, state.moment.moment, state.moment.intensity);
  }
  // v29: a template that names its Vice Wanted applies it whole (Vice
  // Five Star ships Wanted on at level 5).
  if (t.wanted) state.wanted = { ...defaultWanted(), ...t.wanted };
  // v30: a template that names its Vice Radio applies it whole (Vice
  // Radio ships Neon Wave on at 80%).
  if (t.radio) state.radio = { ...defaultRadio(), ...t.radio };
  // v31: a template that names its Vice Map applies it whole (Vice Map
  // ships Radar on at 80%).
  if (t.map) state.map = { ...defaultMap(), ...t.map };
  // v32: a template that names its Vice Phone applies it whole (Vice
  // Phone ships Messages on at 80%).
  if (t.phone) state.phone = { ...defaultPhone(), ...t.phone };
  // v33: a template that names its Vice Ticker applies it whole (Vice
  // Breaking ships the Heist story on at 80%).
  if (t.ticker) state.ticker = { ...defaultTicker(), ...t.ticker };
  // v34: a template that names its Vice Cast applies it whole (Vice
  // Duo ships the Duo cast on at 80%).
  if (t.cast) state.cast = { ...defaultCast(), ...t.cast };
  // v35: a template that names its Vice Ride applies it whole (Vice
  // Ride ships the Coupe ride on at 80%).
  if (t.ride) state.ride = { ...defaultRide(), ...t.ride };
  // v36: a template that names its Vice Neon Sign applies it whole
  // (Vice Neon Sign ships the Neon Nights sign on at 80%).
  if (t.sign) state.sign = { ...defaultSign(), ...t.sign };
  // v37: a template that names its Vice Tag applies it whole (Vice
  // Tag ships the VICE tag on at 80%).
  if (t.tag) state.tag = { ...defaultTag(), ...t.tag };
  if (t.art) state.art = JSON.parse(JSON.stringify(t.art));
  if (t.bubbles) state.bubbles = t.bubbles.map((b) => ({ ...b }));
  if (t.stickers) state.stickers = t.stickers.map((b) => ({ ...b }));
  if (t.canvasBg) state.canvasBg = JSON.parse(JSON.stringify(t.canvasBg));
  if (t.printMarks !== undefined) state.printMarks = t.printMarks;
  if (t.freeform) {
    // items: null means "derive from this template's layout, then tilt".
    const ff = JSON.parse(JSON.stringify(t.freeform));
    ff.layout = state.layout;
    if (!ff.items) {
      ff.items = freeformItemsFor(state.layout);
      const tilts = [-6, 5, -4, 3, -5];
      ff.items.forEach((it, i) => {
        it.rot = (it.rot || 0) + tilts[i % tilts.length];
        if (i === 1) it.x = Math.min(0.95 - it.w, it.x + 0.02);
        if (i === 3) it.y = Math.max(0, it.y - 0.02);
        it.modified = true;
      });
    }
    state.freeform = ff;
  }
  state.panels.forEach((p) => { p.ink = !!t.ink; });
  // v22: a template that names per-panel blend settings applies them
  // (Vice Double Exposure blends photo 2 into panel 1) — entries are
  // partial panel patches, merged onto the existing panel.
  if (t.panels) {
    state.panels.forEach((p, i) => {
      if (t.panels[i]) Object.assign(p, t.panels[i]);
    });
  }
  return true;
}

/** True when the state matches a template's recipe (lab included). */
export function templateMatches(state, key) {
  const t = TEMPLATES[key];
  if (!t) return false;
  for (const f of ['layout', 'grade', 'backdrop', 'blend', 'titleStyle', 'treatment', 'masthead', 'coverLinesOn', 'title']) {
    if (t[f] !== undefined && state[f] !== t[f]) return false;
  }
  // v14: a template that names its fonts only matches when the state
  // carries those faces too (see the applyTemplate fix above).
  if (t.titleFont && state.titleFont !== t.titleFont) return false;
  if (t.bodyFont && state.bodyFont !== t.bodyFont) return false;
  // v18: a template that names its tagline / cover lines / grain /
  // frame colour only matches with those too.
  if (t.tagline !== undefined && state.tagline !== t.tagline) return false;
  if (t.coverLines && JSON.stringify(state.coverLines || []) !== JSON.stringify(t.coverLines)) return false;
  if (t.grain !== undefined && !!state.grain !== !!t.grain) return false;
  if (t.frameColor && (state.frameColor || '') !== t.frameColor) return false;
  // v15: a template that names its Title FX only matches with the same FX.
  if (t.titleFx) {
    const fx = state.titleFx || {};
    for (const k of Object.keys(t.titleFx)) {
      if (fx[k] !== t.titleFx[k]) return false;
    }
  }
  if (t.lab) {
    if ((state.blur || 0) !== (t.lab.blur || 0)) return false;
    if ((state.spotlight || 0) !== (t.lab.spotlight || 0)) return false;
    if ((state.colorPop || 'none') !== (t.lab.colorPop || 'none')) return false;
    if ((state.film || 'none') !== (t.lab.film || 'none')) return false;
  }
  // v21: a template that names a tilt only matches with the same tilt —
  // compared per key, so an old template whose tilt has no shadowStyle
  // still matches a state whose tilt gained one (and vice versa).
  if (t.tilt) {
    const tt = state.tilt || {};
    for (const k of Object.keys(t.tilt)) {
      if (tt[k] !== t.tilt[k]) return false;
    }
  }
  if (t.darkroom) {
    if (JSON.stringify(state.darkroom || {}) !== JSON.stringify(t.darkroom)) return false;
  }
  if (t.art) {
    for (const el of Object.keys(t.art)) {
      if (!!((state.art || {})[el] || {}).on !== !!t.art[el].on) return false;
    }
  }
  if (t.bubbles) {
    if ((state.bubbles || []).length !== t.bubbles.length) return false;
    for (let i = 0; i < t.bubbles.length; i++) {
      if ((state.bubbles[i] || {}).text !== t.bubbles[i].text) return false;
    }
  }
  if (t.glitch) {
    for (const fx of Object.keys(t.glitch)) {
      if (!!((state.glitch || {})[fx] || {}).on !== !!t.glitch[fx].on) return false;
    }
  }
  if (t.palette) {
    const p = state.palette || {};
    if (!!p.enabled !== !!t.palette.enabled) return false;
    if (JSON.stringify(p.stops || []) !== JSON.stringify(t.palette.stops || [])) return false;
  }
  if (t.frame) {
    if ((state.frame || 'none') !== t.frame) return false;
  }
  if (t.stickers) {
    if ((state.stickers || []).length !== t.stickers.length) return false;
    for (let i = 0; i < t.stickers.length; i++) {
      if ((state.stickers[i] || {}).kind !== t.stickers[i].kind) return false;
      // v16: a template that names a sticker colour only matches with it.
      if (t.stickers[i].color && (state.stickers[i] || {}).color !== t.stickers[i].color) return false;
    }
  }
  if (t.canvasBg) {
    if ((state.canvasBg || {}).kind !== t.canvasBg.kind) return false;
  }
  if (t.printMarks !== undefined) {
    if (!!state.printMarks !== !!t.printMarks) return false;
  }
  // v24: a template that names its Vice Clock only matches with the clock
  // on at the same hour.
  if (t.timeOfDay) {
    const tc = state.timeOfDay || {};
    if (!!tc.on !== !!t.timeOfDay.on) return false;
    if (t.timeOfDay.hour !== undefined && tc.hour !== t.timeOfDay.hour) return false;
  }
  // v25: a template that names its Vice Weather only matches with the
  // weather on at the same kind + intensity.
  if (t.weather) {
    const tw = state.weather || {};
    if (!!tw.on !== !!t.weather.on) return false;
    if (t.weather.kind !== undefined && tw.kind !== t.weather.kind) return false;
    if (t.weather.intensity !== undefined && tw.intensity !== t.weather.intensity) return false;
  }
  // v26: a template that names its Vice Era only matches with the era on
  // at the same year + intensity.
  if (t.era) {
    const te = state.era || {};
    if (!!te.on !== !!t.era.on) return false;
    if (t.era.era !== undefined && te.era !== t.era.era) return false;
    if (t.era.intensity !== undefined && te.intensity !== t.era.intensity) return false;
  }
  // v27: a template that names its Vice District only matches with the
  // district on at the same place + intensity.
  if (t.district) {
    const td = state.district || {};
    if (!!td.on !== !!t.district.on) return false;
    if (t.district.district !== undefined && td.district !== t.district.district) return false;
    if (t.district.intensity !== undefined && td.intensity !== t.district.intensity) return false;
  }
  // v28: a template that names its Vice Moment only matches with the
  // moment on at the same moment + intensity.
  if (t.moment) {
    const tm = state.moment || {};
    if (!!tm.on !== !!t.moment.on) return false;
    if (t.moment.moment !== undefined && tm.moment !== t.moment.moment) return false;
    if (t.moment.intensity !== undefined && tm.intensity !== t.moment.intensity) return false;
  }
  // v29: a template that names its Vice Wanted only matches with Wanted
  // on at the same level.
  if (t.wanted) {
    const tw = state.wanted || {};
    if (!!tw.on !== !!t.wanted.on) return false;
    if (t.wanted.level !== undefined && tw.level !== t.wanted.level) return false;
  }
  // v30: a template that names its Vice Radio only matches with Radio
  // on at the same station + volume.
  if (t.radio) {
    const tr = state.radio || {};
    if (!!tr.on !== !!t.radio.on) return false;
    if (t.radio.station !== undefined && tr.station !== t.radio.station) return false;
    if (t.radio.volume !== undefined && tr.volume !== t.radio.volume) return false;
  }
  // v31: a template that names its Vice Map only matches with Map on at
  // the same style + zoom.
  if (t.map) {
    const tm = state.map || {};
    if (!!tm.on !== !!t.map.on) return false;
    if (t.map.style !== undefined && tm.style !== t.map.style) return false;
    if (t.map.zoom !== undefined && tm.zoom !== t.map.zoom) return false;
  }
  // v32: a template that names its Vice Phone only matches with Phone
  // on at the same screen + size.
  if (t.phone) {
    const tp = state.phone || {};
    if (!!tp.on !== !!t.phone.on) return false;
    if (t.phone.screen !== undefined && tp.screen !== t.phone.screen) return false;
    if (t.phone.size !== undefined && tp.size !== t.phone.size) return false;
  }
  // v33: a template that names its Vice Ticker only matches with Ticker
  // on at the same story + speed.
  if (t.ticker) {
    const tt = state.ticker || {};
    if (!!tt.on !== !!t.ticker.on) return false;
    if (t.ticker.story !== undefined && tt.story !== t.ticker.story) return false;
    if (t.ticker.speed !== undefined && tt.speed !== t.ticker.speed) return false;
  }
  // v34: a template that names its Vice Cast only matches with Cast
  // on at the same cast + size.
  if (t.cast) {
    const tc = state.cast || {};
    if (!!tc.on !== !!t.cast.on) return false;
    if (t.cast.cast !== undefined && tc.cast !== t.cast.cast) return false;
    if (t.cast.size !== undefined && tc.size !== t.cast.size) return false;
  }
  // v35: a template that names its Vice Ride only matches with Ride
  // on at the same ride + size.
  if (t.ride) {
    const tr = state.ride || {};
    if (!!tr.on !== !!t.ride.on) return false;
    if (t.ride.ride !== undefined && tr.ride !== t.ride.ride) return false;
    if (t.ride.size !== undefined && tr.size !== t.ride.size) return false;
  }
  // v36: a template that names its Vice Neon Sign only matches with
  // Sign on at the same sign + size.
  if (t.sign) {
    const ts = state.sign || {};
    if (!!ts.on !== !!t.sign.on) return false;
    if (t.sign.sign !== undefined && ts.sign !== t.sign.sign) return false;
    if (t.sign.size !== undefined && ts.size !== t.sign.size) return false;
  }
  // v37: a template that names its Vice Tag only matches with Tag
  // on at the same tag + size.
  if (t.tag) {
    const tt = state.tag || {};
    if (!!tt.on !== !!t.tag.on) return false;
    if (t.tag.tag !== undefined && tt.tag !== t.tag.tag) return false;
    if (t.tag.size !== undefined && tt.size !== t.tag.size) return false;
  }
  if (t.freeform) {
    const ff = state.freeform || {};
    if (!!ff.on !== !!t.freeform.on) return false;
    if (t.freeform.title) {
      const tt = ff.title || {};
      if (tt.x !== t.freeform.title.x || tt.y !== t.freeform.title.y || (tt.rot || 0) !== t.freeform.title.rot) return false;
    }
  }
  return state.panels.every((p) => p.ink === !!t.ink);
}
